#include "guest.h"

#include <algorithm>
#include <cstring>
#include <vector>

#include "hle.h"

extern "C" {
// Generated by guest/postprocess.py: every exported guest symbol with a plain C name.
typedef u32 *(*khvr_sym_fn)(w2c_khdays *);
struct khvr_guest_symbol {
    const char *name;
    khvr_sym_fn get;
};
extern const struct khvr_guest_symbol khvr_guest_symbols[];
extern const unsigned khvr_guest_symbol_count;
}

namespace khvr::hle {

namespace {
w2c_khdays gInstance;
}

w2c_khdays *Guest() { return &gInstance; }

std::string ReadString(uint32_t a, size_t max) {
    std::string s;
    for (size_t i = 0; i < max && a + i < GuestMemSize(); ++i) {
        char c = static_cast<char>(GuestMem()[a + i]);
        if (!c) break;
        s += c;
    }
    return s;
}

uint32_t BusRead(uint32_t a, uint32_t size) {
    if (((a >> 24) | 2u) == 6u) return static_cast<uint32_t>(IoRead(a, size));
    switch (size) {
    case 1: return Read8(a);
    case 2: return Read16(a);
    default: return Read32(a);
    }
}

void BusWrite(uint32_t a, uint32_t v, uint32_t size) {
    if (((a >> 24) | 2u) == 6u) return IoWrite(a, v, size);
    switch (size) {
    case 1: Write8(a, static_cast<uint8_t>(v)); break;
    case 2: Write16(a, static_cast<uint16_t>(v)); break;
    default: Write32(a, v); break;
    }
}

uint32_t SymbolAddress(const char *name) {
    static std::vector<std::pair<std::string, khvr_sym_fn>> table = [] {
        std::vector<std::pair<std::string, khvr_sym_fn>> t;
        for (unsigned i = 0; i < khvr_guest_symbol_count; ++i)
            t.emplace_back(khvr_guest_symbols[i].name, khvr_guest_symbols[i].get);
        std::sort(t.begin(), t.end());
        return t;
    }();
    auto it = std::lower_bound(table.begin(), table.end(), std::make_pair(std::string(name), khvr_sym_fn()),
                               [](const auto &a, const auto &b) { return a.first < b.first; });
    if (it == table.end() || it->first != name) return 0;
    return *it->second(Guest());
}

uint32_t CallGuest(uint32_t index, uint32_t a0, uint32_t a1, uint32_t a2, uint32_t a3) {
    wasm_rt_funcref_table_t &t = Guest()->w2c_0x5F_indirect_function_table;
    if (index == 0 || index >= t.size || !t.data[index].func) {
        Log("CallGuest: bad function index %u", index);
        return 0;
    }
    // Every guest function takes its module instance first and then i32 parameters; on AArch64
    // and x86-64 the extra arguments of this widest signature are simply ignored, like on ARM.
    using Fn = u32 (*)(void *, u32, u32, u32, u32);
    return reinterpret_cast<Fn>(t.data[index].func)(t.data[index].module_instance, a0, a1, a2, a3);
}

}  // namespace khvr::hle
